    55→function parseSms(content: string) {
    56→  // Handle SMSTO:phone:message format (generated by the QR registry)
    57→  const smsto = content.match(/^SMSTO:([^:]*):?(.*)?$/i);
    58→  if (smsto) {
    59→    return { to: smsto[1]?.trim() ?? "", body: smsto[2]?.trim() ?? "" };
    60→  }
    61→  // Handle sms:phone?body=message format
    62→  try {
    63→    const url = new URL(content);
    64→    const to = url.pathname.replace(/^\//, "");
    65→    const body = url.searchParams.get("body") ?? "";
    66→    return { to, body };
    67→  } catch { return { to: content.replace(/^sms[to]*:/i, "").split("?")[0], body: "" }; }
    68→}
