   102→function icalToDate(dt: string): Date | null {
   103→  if (!dt) return null;
   104→  try {
   105→    const y = dt.slice(0, 4), mo = dt.slice(4, 6), d = dt.slice(6, 8);
   106→    const h = dt.slice(9, 11) || "00", mi = dt.slice(11, 13) || "00";
   107→    return new Date(`${y}-${mo}-${d}T${h}:${mi}:00`);
   108→  } catch { return null; }
   109→}
   110→
   111→function formatEventDate(dt: string): string {
   112→  if (!dt) return "";
   113→  const date = icalToDate(dt);
   114→  if (!date) return dt;
   115→  return date.toLocaleDateString(undefined, { weekday: "long", year: "numeric", month: "long", day: "numeric" });
   116→}
   117→
   118→function formatEventTime(dt: string): string {
   119→  if (!dt) return "";
   120→  const date = icalToDate(dt);
   121→  if (!date) return "";
   122→  return date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
   123→}
