   301→const EXPAND_THRESHOLD = 120;
   302→
   303→const ContentCard = React.memo(function ContentCard({ content, contentType, parsedPayment, isDeactivated, onOpenContent, hideOpenAction, templateKey }: Props) {
   304→  const { colors, isDark } = useTheme();
   305→  const [copied, setCopied] = React.useState(false);
   306→  const [contentExpanded, setContentExpanded] = React.useState(false);
   307→
   308→  const isLongContent = content.length > EXPAND_THRESHOLD || content.includes("\n");
   309→  const cfg = getQrTypeStyle(contentType, templateKey);
   310→  const hasOpenAction = !isDeactivated && !hideOpenAction && contentType !== "text" && contentType !== "product";
   311→
   312→  async function handleCopy() {
   313→    await Clipboard.setStringAsync(content);
   314→    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
   315→    if (Platform.OS !== "android") {
   316→      setCopied(true);
   317→      setTimeout(() => setCopied(false), 2000);
   318→    }
   319→  }
   320→
   321→  const URL_LIKE_TYPES = new Set(["url", "instagram", "twitter", "youtube", "linkedin", "telegram", "facebook", "spotify", "discord", "tiktok", "zoom", "calendly", "appdownload", "app", "social", "media", "paypal", "venmo", "mobilepay", "reviewpage", "menucatalogue", "donation", "razorpay", "snapchat"]);
   322→  const isUrlLike = URL_LIKE_TYPES.has(contentType);
   323→
   324→  const wifi = contentType === "wifi" ? parseWifi(content) : null;
   325→  const contact = contentType === "contact" ? parseContact(content) : null;
   326→  const smsData = contentType === "sms" ? parseSms(content) : null;
   327→  const eventData = (contentType === "event" || contentType === "calendar") ? parseEvent(content) : null;
   328→  const whatsappData = contentType === "whatsapp" ? parseWhatsApp(content) : null;
   329→  const emailData = contentType === "email" ? parseEmail(content) : null;
   330→  const phoneStr = contentType === "phone" ? parsePhone(content) : null;
   331→  const locationData = contentType === "location" ? parseLocation(content) : null;
   332→  const cryptoData = contentType === "crypto" ? parseCrypto(content) : null;
   333→  const eventOver = eventData ? isEventPast(eventData.dtend, eventData.dtstart) : false;
   334→
   335→  const smartActionLabel = React.useMemo((): string => {
   336→    if ((contentType === "contact" || contentType === "mecard") && contact) {
   337→      if (contact.phone) return "Call Now";
   338→      if (contact.email) return "Send Email";
   339→    }
   340→    return cfg.openLabel;
   341→  }, [contentType, contact, cfg.openLabel]);
   342→
   343→  const smartActionIcon = React.useMemo((): keyof typeof Ionicons.glyphMap => {
   344→    if ((contentType === "contact" || contentType === "mecard") && contact) {
   345→      if (contact.phone) return "call-outline";
   346→      if (contact.email) return "mail-outline";
   347→    }
   348→    return "open-outline";
   349→  }, [contentType, contact]);
