   354→  if (contentType === "encrypted") {
   355→    const preview = content.length > 40 ? content.slice(0, 40) + "…" : content;
   356→    const isBase64 = /^[A-Za-z0-9+/]{20,}={0,2}$/.test(content.trim());
   357→    const isHex = /^[0-9a-fA-F]{40,}$/.test(content.trim());
   358→    const dataHint = isBase64 ? "Base64-encoded" : isHex ? "Hex-encoded" : "Proprietary";
   359→    return (
   360→      <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.warning + "50" }]}>
   361→        <LinearGradient colors={[colors.warning + (isDark ? "20" : "10"), "transparent"]} style={StyleSheet.absoluteFill} />
