   113→  function buildUpiUrl(parsedPayment: NonNullable<typeof safety.parsedPayment>): string | null {
   114→    const { vpa, recipientName, amount, currency } = parsedPayment;
   115→    if (!vpa) return null;
   116→    // Validate VPA format before building the link — prevents malformed deep links
   117→    const vpaRegex = /^[a-zA-Z0-9._\-]+@[a-zA-Z0-9]+$/;
   118→    if (!vpaRegex.test(vpa.trim())) return null;
   119→    // mode=02 forces payee name resolution from NPCI; mc=0000 is standard merchant code
   120→    let url = `upi://pay?pa=${encodeURIComponent(vpa.trim())}&mc=0000&mode=02`;
   121→    if (recipientName) url += `&pn=${encodeURIComponent(recipientName.trim())}`;
   122→    const parsedAmount = amount ? parseFloat(amount) : 0;
   123→    if (parsedAmount > 0) url += `&am=${parsedAmount.toFixed(2)}`;
   124→    // cu=INR always present — some UPI apps reject links without it
   125→    url += `&cu=${currency || "INR"}`;
   126→    return url;
   127→  }
