    }
    return { level: "safe" as const, label: "YOUR QR", reason: "You created this QR code", color: colors.safe };
  }

  const isCommunityAvailable = trust.score >= 0;

  if (isCommunityAvailable) {
    if (trust.label === "Trusted" || trust.label === "Likely Safe") {
