   105→  if (ct === "sms") return c.replace(/^SMSTO?:/i, "").split(":")[0].trim() || c;
   106→  if (ct === "crypto") {
   107→    const m = c.match(/^(bitcoin|ethereum|litecoin|solana):([^?]{6,})/i);
   108→    if (m) return `${m[1].charAt(0).toUpperCase() + m[1].slice(1)}: ${m[2].slice(0, 14)}…`;
   109→  }
   110→  if (ct === "calendar" || ct === "event") {
   111→    const summary = c.match(/SUMMARY:([^\r\n]+)/)?.[1];
   112→    if (summary) return summary.trim();
   113→  }
   114→  if (ct === "location") {
   115→    const q = c.match(/[?&]q=([^&\n]+)/)?.[1];
   116→    if (q) return decodeURIComponent(q);
   117→    const geo = c.replace(/^geo:/i, "").split("?")[0];
   118→    if (geo && geo !== c) return `Location (${geo})`;
   119→  }
   120→  if (["upi", "scantopay", "paymentlink", "payment"].includes(ct)) {
   121→    const vpa = c.match(/pa=([^&\s]+)/i)?.[1];
   122→    if (vpa) return decodeURIComponent(vpa);
   123→  }
   124→  if (c.startsWith("http")) {
   125→    try { return new URL(c).hostname.replace(/^www\./, ""); } catch {}
   126→  }
   127→
   128→  return `QR Code ${index + 1}`;
   129→}
