   112→export function useQrData(id: string, userId: string | null) {
   113→  const [totalScans, setTotalScans] = useState(0);
   114→  const [totalComments, setTotalComments] = useState(0);
   115→  const [ownerInfo, setOwnerInfo] = useState<QrOwnerInfo | null>(null);
   116→  const [isQrOwner, setIsQrOwner] = useState(false);
   117→
   118→  const ownerFetchedForId = useRef<string | null>(null);
   119→
   120→  const { data: result, isPending, isError } = useQuery<QrFetchResult>({
   121→    queryKey: ["qr-detail", id, userId],
   122→    queryFn: () => fetchQrData(id, userId),
   123→    staleTime: 5 * 60 * 1000,
   124→    gcTime: 30 * 60 * 1000,
   125→    refetchOnWindowFocus: false,
   126→    retry: false,
   127→  });
   128→
   129→  const loading = isPending;
   130→  const offlineMode = result?.status === "offline";
   131→  const loadError = result?.status === "error" || isError;
   132→  const qrCode: QrDetail | null = result?.status === "data" ? result.detail.qrCode : null;
   133→  const offlineContent = result?.status === "offline" ? result.content : null;
   134→  const offlineContentType = result?.status === "offline" ? result.contentType : "text";
   135→
   136→  useEffect(() => {
   137→    if (result?.status !== "data") return;
   138→    const detail = result.detail;
   139→    setTotalScans(detail.totalScans || 0);
   140→    setTotalComments(detail.totalComments || 0);
   141→
   142→    if (detail.ownerInfo) {
   143→      setOwnerInfo(detail.ownerInfo);
   144→      setIsQrOwner(userId === detail.ownerInfo.ownerId);
   145→    }
   146→
   147→    if (!result.isFreshFetch) return;
   148→
   149→    if (userId && qrCode) {
   150→      recordViewedLocally(id, qrCode.content, qrCode.contentType, userId).catch(() => {});
   151→    }
   152→
   153→    if (ownerFetchedForId.current === id) return;
   154→    ownerFetchedForId.current = id;
   155→
   156→    let cancelled = false;
   157→    (async () => {
   158→      let ownerData: any = null;
   159→      try {
   160→        const owner = await getQrOwnerInfo(id);
   161→        if (!cancelled && owner) {
   162→          setOwnerInfo(owner);
   163→          setIsQrOwner(userId === owner.ownerId);
   164→          ownerData = owner;
   165→        }
   166→      } catch {}
   167→      if (!cancelled) {
   168→        setCachedQrDetail(id, userId, { ...detail, ownerInfo: ownerData }).catch(() => {});
   169→      }
   170→    })();
   171→    return () => { cancelled = true; };
   172→  }, [result, id, userId]);
   173→
   174→  useEffect(() => {
   175→    if (!result || result.status !== "data") {
   176→      ownerFetchedForId.current = null;
   177→    }
   178→  }, [id]);
   179→
   180→  useEffect(() => {
   181→    if (offlineMode) return;
   182→    const unsub = subscribeToQrStats(id, ({ scanCount, commentCount }) => {
   183→      setTotalScans(scanCount);
   184→      setTotalComments(commentCount);
   185→    });
   186→    return unsub;
   187→  }, [id, offlineMode]);
   188→
   189→  return {
   190→    qrCode,
   191→    totalScans,
   192→    totalComments,
   193→    loading,
   194→    loadError,
   195→    offlineMode,
   196→    offlineContent,
   197→    offlineContentType,
   198→    ownerInfo,
   199→    isQrOwner,
   200→  };
   201→}
